const items = $input.all() || [];
const extractDateScore = (name, createdTime) => {
  const m = String(name || '').match(/(?:^|_)(\d{4})(\d{2})(\d{2})(?:_|\.|$)/);
  if (m) return Number(`${m[1]}${m[2]}${m[3]}`);
  const ts = Date.parse(createdTime || '');
  return Number.isFinite(ts) ? ts : Number.MAX_SAFE_INTEGER;
};

const pdfs = items.filter((item) => {
  const j = item.json || {};
  const mime = String(j.mimeType || '').toLowerCase();
  const name = String(j.name || j.originalFilename || '').toLowerCase();
  return mime === 'application/pdf' || name.endsWith('.pdf');
});

pdfs.sort((a, b) => {
  const ja = a.json || {};
  const jb = b.json || {};
  return extractDateScore(ja.name, ja.createdTime) - extractDateScore(jb.name, jb.createdTime);
});

return pdfs.map((item) => {
  const j = item.json || {};
  const fileName = j.name || j.originalFilename || 'documento.pdf';
  const cleanFileName = fileName
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-zA-Z0-9._-]/g, '_');
  const m = fileName.match(/(?:^|_)(\d{4})(\d{2})(\d{2})(?:_|\.|$)/);
  const publishedOn = m ? `${m[1]}-${m[2]}-${m[3]}` : null;
  return {
    json: {
      source_mode: 'gdrive',
      is_webhook: false,
      force_reingest: false,
      google_drive_file_id: j.id,
      file_name: fileName,
      clean_file_name: cleanFileName,
      file_size: j.size ? Number(j.size) : null,
      folder_category: '00_registros_oficiales',
      storage_bucket: 'legal-documents',
      storage_path: `00_registros_oficiales/${cleanFileName}`,
      google_drive_path: `01_PDF_Original/00_registros_oficiales/${fileName}`,
      published_on: publishedOn,
      norm_code: null,
      version_title: null,
      official_registry_cite: null,
      pdf_signed_url: null
    }
  };
});

const raw = $input.first()?.json || {};
let body = raw.body !== undefined ? raw.body : raw;
if (typeof body === 'string') {
  try { body = JSON.parse(body); } catch (e) {}
}

const normalizeCleanName = (name) =>
  String(name || 'documento.pdf')
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-zA-Z0-9._-]/g, '_');

const parseDateFromName = (name) => {
  const m = String(name || '').match(/(?:^|_)(\d{4})(\d{2})(\d{2})(?:_|\.|$)/);
  return m ? `${m[1]}-${m[2]}-${m[3]}` : null;
};

// Si es un array de elementos directamente
const list = Array.isArray(body)
  ? body
  : (Array.isArray(body.google_drive_files) ? body.google_drive_files : (Array.isArray(body.google_drive_file_ids) ? body.google_drive_file_ids.map(id => ({ google_drive_file_id: id })) : null));

if (list) {
  return list.map((entry) => {
    const fileId = entry.google_drive_file_id || entry.id;
    const fileName = entry.file_name || entry.name || null;
    const cleanFileName = normalizeCleanName(fileName || `${fileId}.pdf`);
    const folderCategory = entry.folder_category || body.folder_category || '00_registros_oficiales';
    const isDrive = Boolean(fileId || entry.source_mode === 'gdrive' || entry.source_mode === 'google_drive');
    return {
      json: {
        source_mode: isDrive ? 'gdrive' : (entry.base64_pdf ? 'inline' : 'storage'),
        is_webhook: true,
        force_reingest: Boolean(entry.force_reingest ?? body.force_reingest),
        google_drive_file_id: fileId,
        file_name: fileName,
        clean_file_name: cleanFileName,
        file_size: entry.file_size ? Number(entry.file_size) : null,
        folder_category: folderCategory,
        storage_bucket: entry.storage_bucket || body.storage_bucket || 'legal-documents',
        storage_path: entry.storage_path || (fileName ? `${folderCategory}/${cleanFileName}` : null),
        google_drive_path: entry.google_drive_path || (fileName ? `01_PDF_Original/${folderCategory}/${fileName}` : null),
        published_on: entry.published_on || parseDateFromName(fileName),
        norm_code: entry.norm_code || null,
        version_title: entry.version_title || null,
        official_registry_cite: entry.official_registry_cite || null,
        pdf_signed_url: entry.pdf_signed_url || null,
        base64_pdf: entry.base64_pdf || null
      }
    };
  });
}

if (body.google_drive_file_id || body.source_mode === 'google_drive' || body.source_mode === 'gdrive') {
  const fileId = body.google_drive_file_id || body.id;
  const fileName = body.file_name || null;
  const cleanFileName = normalizeCleanName(fileName || `${fileId}.pdf`);
  const folderCategory = body.folder_category || '00_registros_oficiales';
  return [{
    json: {
      source_mode: 'gdrive',
      is_webhook: true,
      force_reingest: Boolean(body.force_reingest),
      google_drive_file_id: fileId,
      file_name: fileName,
      clean_file_name: cleanFileName,
      file_size: body.file_size ? Number(body.file_size) : null,
      folder_category: folderCategory,
      storage_bucket: body.storage_bucket || 'legal-documents',
      storage_path: body.storage_path || (fileName ? `${folderCategory}/${cleanFileName}` : null),
      google_drive_path: body.google_drive_path || (fileName ? `01_PDF_Original/${folderCategory}/${fileName}` : null),
      published_on: body.published_on || parseDateFromName(fileName),
      norm_code: body.norm_code || null,
      version_title: body.version_title || null,
      official_registry_cite: body.official_registry_cite || null,
      pdf_signed_url: null
    }
  }];
}

const fileName = body.file_name || 'documento.pdf';
const cleanFileName = normalizeCleanName(fileName);
const folderCategory = body.folder_category || '00_registros_oficiales';
return [{
  json: {
    source_mode: body.base64_pdf ? 'inline' : 'storage',
    is_webhook: true,
    force_reingest: Boolean(body.force_reingest),
    google_drive_file_id: body.google_drive_file_id || null,
    file_name: fileName,
    clean_file_name: cleanFileName,
    file_size: body.file_size ? Number(body.file_size) : null,
    folder_category: folderCategory,
    storage_bucket: body.storage_bucket || 'legal-documents',
    storage_path: body.storage_path || `${folderCategory}/${cleanFileName}`,
    google_drive_path: body.google_drive_path || null,
    published_on: body.published_on || parseDateFromName(fileName),
    norm_code: body.norm_code || null,
    version_title: body.version_title || null,
    official_registry_cite: body.official_registry_cite || null,
    pdf_signed_url: body.pdf_signed_url || null,
    base64_pdf: body.base64_pdf || null
  }
}];

const ctx = $('Loop Documentos 1x1').item.json || {};
const existing = $input.first()?.json || {};
return [{
  json: {
    is_webhook: Boolean(ctx.is_webhook),
    status: 'skipped_duplicate',
    file_name: ctx.file_name || existing.file_name || null,
    google_drive_file_id: ctx.google_drive_file_id,
    document_id: existing.id || null
  }
}];

const item = $input.first() || {};
const ctx = $('Loop Documentos 1x1').first()?.json || {};
const driveJson = item.json || {};
const binMeta = item.binary?.data || {};

const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
let sha256 = null;
try {
  const crypto = require('crypto');
  sha256 = crypto.createHash('sha256').update(buffer).digest('hex');
} catch (_) {
  sha256 = null;
}

const fileName = driveJson.name || binMeta.fileName || ctx.file_name || 'documento.pdf';
const cleanFileName = fileName
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .replace(/[^a-zA-Z0-9._-]/g, '_');
const m = fileName.match(/(?:^|_)(\d{4})(\d{2})(\d{2})(?:_|\.|$)/);
const publishedOn = ctx.published_on || (m ? `${m[1]}-${m[2]}-${m[3]}` : null);
const folderCategory = ctx.folder_category || '00_registros_oficiales';
const storageBucket = ctx.storage_bucket || 'legal-documents';
const storagePath = `${folderCategory}/${cleanFileName}`;

return [{
  json: {
    meta: {
      is_webhook: Boolean(ctx.is_webhook),
      source_mode: 'gdrive',
      file_name: fileName,
      clean_file_name: cleanFileName,
      file_size: buffer.length,
      sha256,
      folder_category: folderCategory,
      norm_code: ctx.norm_code || null,
      version_title: ctx.version_title || null,
      published_on: publishedOn,
      official_registry_cite: ctx.official_registry_cite || null,
      google_drive_file_id: ctx.google_drive_file_id || driveJson.id || null,
      google_drive_path: ctx.google_drive_path || `01_PDF_Original/${folderCategory}/${fileName}`,
      storage_bucket: storageBucket,
      storage_path: storagePath
    },
    base64_pdf: buffer.toString('base64')
  },
  binary: item.binary
}];

const prev = $('Preparar Drive + Base64').first()?.json || {};
const mirrorResp = $input.first()?.json || {};
return [{
  json: {
    meta: {
      ...(prev.meta || {}),
      storage_mirror_ok: !mirrorResp.error,
      storage_mirror_key: mirrorResp.Key || prev.meta?.storage_path || null
    },
    base64_pdf: prev.base64_pdf || ''
  }
}];

const ctx = $('Loop Documentos 1x1').first()?.json || {};
let base64Pdf = ctx.base64_pdf || '';
let byteLength = ctx.file_size || null;
let sha256 = null;

if (!base64Pdf) {
  const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
  base64Pdf = buffer.toString('base64');
  byteLength = byteLength || buffer.length;
  try {
    const crypto = require('crypto');
    sha256 = crypto.createHash('sha256').update(buffer).digest('hex');
  } catch (_) {
    sha256 = null;
  }
}

return [{
  json: {
    meta: {
      is_webhook: Boolean(ctx.is_webhook),
      source_mode: ctx.source_mode || 'storage',
      file_name: ctx.file_name || 'documento.pdf',
      clean_file_name: ctx.clean_file_name || 'documento.pdf',
      file_size: byteLength,
      sha256,
      folder_category: ctx.folder_category || '00_registros_oficiales',
      norm_code: ctx.norm_code || null,
      version_title: ctx.version_title || null,
      published_on: ctx.published_on || null,
      official_registry_cite: ctx.official_registry_cite || null,
      google_drive_file_id: ctx.google_drive_file_id || null,
      google_drive_path: ctx.google_drive_path || null,
      storage_bucket: ctx.storage_bucket || 'legal-documents',
      storage_path: ctx.storage_path || null
    },
    base64_pdf: base64Pdf
  }
}];

