const unified = $('Unificar Meta Base64').first()?.json || {};
const meta = unified.meta || {};
const blockCtx = $('Loop Actos 1x1').first()?.json || {};
const actMeta = blockCtx.act_meta || {};
const blockSpec = blockCtx.block_spec || {};
const resp = $input.first()?.json || {};

if (resp.error) {
  throw new Error(`Error API Gemini en bloque ${blockSpec.bloque_num || 1}: ${JSON.stringify(resp.error)}`);
}

const candidate = resp.candidates?.[0];
const finishReason = candidate?.finishReason;
let rawText = candidate?.content?.parts?.[0]?.text || resp.text || '';
if (!rawText) {
  throw new Error(`Gemini no devolvió contenido en bloque ${blockSpec.bloque_num || 1} (finishReason=${finishReason || 'unknown'})`);
}

const tryParseJsonWithRepair = (text, finishReason) => {
  let clean = String(text || '').trim();
  if (clean.startsWith('```')) {
    clean = clean.replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/i, '').trim();
  }
  clean = clean
    .replace(/\\([“”«»])/g, '$1')
    .replace(/\\([^"\\/bfnrtu])/g, '$1');

  try { return JSON.parse(clean); } catch (e1) {}
  if (clean.endsWith('\\')) clean = clean.slice(0, -1);

  let inString = false, escaped = false;
  const stack = [];
  for (let i = 0; i < clean.length; i++) {
    const ch = clean[i];
    if (escaped) { escaped = false; continue; }
    if (ch === '\\' && inString) { escaped = true; continue; }
    if (ch === '"') { inString = !inString; continue; }
    if (!inString) {
      if (ch === '{') stack.push('}');
      else if (ch === '[') stack.push(']');
      else if (ch === '}' || ch === ']') {
        if (stack.length && stack[stack.length - 1] === ch) stack.pop();
      }
    }
  }

  let repaired = clean;
  if (inString) {
    const lastNl = repaired.lastIndexOf('\n');
    if (lastNl !== -1 && lastNl > repaired.length - 200) {
      repaired = repaired.slice(0, lastNl);
    }
    repaired += '"';
  }
  const stackCopy = [...stack];
  while (stackCopy.length > 0) repaired += '\n' + stackCopy.pop();

  try {
    return JSON.parse(repaired);
  } catch (errStack) {
    const lastBrace = clean.lastIndexOf('}');
    if (lastBrace !== -1) {
      let sub = clean.slice(0, lastBrace + 1);
      const subStack = [];
      let inS = false, esc = false;
      for (let i = 0; i < sub.length; i++) {
        const c = sub[i];
        if (esc) { esc = false; continue; }
        if (c === '\\' && inS) { esc = true; continue; }
        if (c === '"') { inS = !inS; continue; }
        if (!inS) {
          if (c === '{') subStack.push('}');
          else if (c === '[') subStack.push(']');
          else if ((c === '}' || c === ']') && subStack.length && subStack[subStack.length - 1] === c) subStack.pop();
        }
      }
      let subRep = sub;
      if (inS) subRep += '"';
      while (subStack.length > 0) subRep += '\n' + subStack.pop();
      try { return JSON.parse(subRep); } catch (eSub) {}
    }
    throw new Error(`JSON inválido o truncado en bloque ${blockSpec.bloque_num || 1} (finishReason=${finishReason}): ${errStack.message}`);
  }
};

const parsed = tryParseJsonWithRepair(rawText, finishReason);

const roCite = blockCtx.ro_cite || parsed.registro_oficial_cita || meta.official_registry_cite || 'Registro Oficial';
const rawDate = blockCtx.ro_date || parsed.registro_oficial_fecha || meta.published_on;
const roDate = /^\d{4}-\d{2}-\d{2}$/.test(String(rawDate || ''))
  ? String(rawDate)
  : new Date().toISOString().split('T')[0];

const parseFiscalYear = (val, fallback) => {
  if (typeof val === 'number' && Number.isInteger(val)) return val;
  const s = String(val || '').trim();
  const m = s.match(/\b(19\d\d|20\d\d)\b/);
  if (m) return Number(m[1]);
  const fb = Number(fallback);
  return Number.isInteger(fb) ? fb : null;
};

const parseDateIso = (val, fallback = null) => {
  if (!val) return fallback;
  const s = String(val).trim();
  if (/^\d{4}-\d{2}-\d{2}$/.test(s)) return s;
  const m = s.match(/(\d{4})[-/](\d{1,2})[-/](\d{1,2})/);
  if (m) return `${m[1]}-${m[2].padStart(2, '0')}-${m[3].padStart(2, '0')}`;
  return fallback;
};

const parseNumeric = (v) => {
  if (v === null || v === undefined || v === '') return null;
  if (typeof v === 'number') return Number.isFinite(v) ? v : null;
  const s = String(v).trim();
  if (!s || /adelante|infinito/i.test(s)) return null;
  let clean = s.replace(/[$%\s]/g, '');
  if (/^\d{1,3}(,\d{3})+(\.\d+)?$/.test(clean)) clean = clean.replace(/,/g, '');
  else if (/^\d{1,3}(\.\d{3})+(,\d+)?$/.test(clean)) clean = clean.replace(/\./g, '').replace(',', '.');
  else if (/^\d+,\d{1,4}$/.test(clean)) clean = clean.replace(',', '.');
  const n = Number(clean);
  return Number.isFinite(n) ? n : v;
};

const normalizeNormCode = (code) => {
  let c = String(code || '').trim().toUpperCase();
  if (!c) return null;
  const decMatch = c.match(/(?:DECRETO(?:\s+EJECUTIVO)?|DEC|NO\.?)\s*[-_N°#]?\s*(\d+)/i);
  if (decMatch && !c.includes('LEY') && !c.includes('RESOLUCI') && !c.includes('CIRCULAR')) {
    return 'DE-' + decMatch[1];
  }
  if (c.startsWith('NO.-') && /^NO\.-\d+$/.test(c)) {
    return 'DE-' + c.replace('NO.-', '');
  }
  if (c === 'RLRTI' || c === 'REGLAMENTO LRTI') return 'RALRTI';
  if (c === 'CODIGO TRIBUTARIO' || c === 'CÓDIGO TRIBUTARIO') return 'CT';
  if (c === 'LEY DE REGIMEN TRIBUTARIO INTERNO' || c === 'LEY DE RÉGIMEN TRIBUTARIO INTERNO') return 'LRTI';
  return c.replace(/\s+/g, '-');
};

const normalizeTargetArtId = (rawId) => {
  if (!rawId) return null;
  let s = String(rawId).trim();
  if (s.includes(',')) s = s.split(',')[0].trim();
  s = s.replace(/^(?:art(?:[íi]culo|\.)?\s*)+/i, '').trim();
  s = s.replace(/(?:\.[a-zA-Z]+|\s+(?:literal|inciso|numeral|ordinal|p[aá]rrafo)\b.*)$/i, '').trim();
  s = s.replace(/^[:.-]+|[:.-]+$/g, '').trim();
  return s || null;
};

const validTypes = new Set(['constitution','law','organic_law','regulation','decree','resolution','ordinance','circular','agreement','other']);

let acts = Array.isArray(parsed.actos_tributarios) ? parsed.actos_tributarios : [];
const act = acts[0] || {};

const normCode = actMeta.codigo_norma || normalizeNormCode(act.codigo_norma) || 'NORMA';
const rawNormType = String(actMeta.tipo_norma || act.tipo_norma || 'law').toLowerCase();
const normType = validTypes.has(rawNormType) ? rawNormType : 'law';
const tituloNorma = actMeta.titulo_norma || act.titulo_norma || normCode;
const isFeErratas = Boolean(actMeta.es_fe_erratas || act.es_fe_erratas) || /errata/i.test(`${tituloNorma} ${roCite}`);
const periodicity = String(actMeta.periodicidad_tributaria || act.periodicidad_tributaria || 'monthly').toLowerCase() === 'annual' ? 'annual' : 'monthly';
const expressValidFrom = parseDateIso(actMeta.vigencia_expresa_fecha || act.vigencia_expresa_fecha, roDate);

// Unificar artículos de todos los elementos de actos_tributarios devueltos en este bloque
const rawArticles = [];
if (acts.length > 0) {
  for (const a of acts) {
    if (Array.isArray(a.articulos)) rawArticles.push(...a.articulos);
  }
} else if (Array.isArray(parsed.articulos)) {
  rawArticles.push(...parsed.articulos);
}

const normalizeTablesList = (rawTables, artNum, finalTitle) => {
  if (!Array.isArray(rawTables)) return [];
  return rawTables.map((tbl, tblIdx) => {
    const cols = Array.isArray(tbl.columns_schema)
      ? tbl.columns_schema.map((c, ci) => typeof c === 'string'
          ? { key: c.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9]+/g, '_').replace(/^_|_$/g, '') || `col_${ci}`, type: 'text', label: c }
          : c)
      : [];
    const rows = Array.isArray(tbl.rows_data)
      ? tbl.rows_data.map((r) => {
          if (Array.isArray(r) && cols.length) {
            const obj = {};
            cols.forEach((c, idx) => {
              obj[c.key] = (c.type === 'currency' || c.type === 'percentage' || c.type === 'number') ? parseNumeric(r[idx]) : r[idx];
            });
            return obj;
          }
          if (r && typeof r === 'object') {
            const out = {};
            for (const [k, val] of Object.entries(r)) {
              const numKeys = new Set(['fraccion_basica', 'exceso_hasta', 'impuesto_fraccion_basica', 'porcentaje_excedente']);
              out[k] = numKeys.has(k) ? parseNumeric(val) : val;
            }
            return out;
          }
          return r;
        })
      : [];
    const fiscalYr = parseFiscalYear(tbl.fiscal_year, roDate.slice(0, 4));
    return {
      code: tbl.code || `TBL_${normCode}_${String(artNum).replace(/[^A-Za-z0-9_]/g, '_')}_${fiscalYr || 'GEN'}${rawTables.length > 1 ? '_' + (tblIdx + 1) : ''}`,
      titulo_tabla: tbl.titulo_tabla || `Tabla ${finalTitle}`,
      descripcion: tbl.descripcion || `${tituloNorma} (${roCite})`,
      categoria_tabla: tbl.categoria_tabla || 'other',
      fiscal_year: fiscalYr,
      valid_from: parseDateIso(tbl.valid_from, expressValidFrom),
      valid_until: parseDateIso(tbl.valid_until, null),
      markdown_tabla: tbl.markdown_tabla || null,
      columns_schema: cols,
      rows_data: rows
    };
  });
};

const consolidatedArticles = [];
const seen = new Set();

for (const art of rawArticles) {
  const rawNum = String(art.numero || consolidatedArticles.length + 1).trim();
  const rawType = String(art.tipo_estructura || 'article').toLowerCase();

  let structType = 'article';
  if (rawType.includes('transitoria')) structType = 'transitory';
  else if (rawType.includes('final')) structType = 'final';
  else if (rawType.includes('reform') || rawType.includes('derogatoria')) structType = 'reform';
  else if (rawType.includes('general')) structType = 'other';

  const key = `${structType}_${rawNum.toLowerCase()}`;
  if (seen.has(key)) continue;
  seen.add(key);

  const cleanHeader = String(art.encabezado || '')
    .replace(/^(?:Art(?:[íi]culo|\.)?\s*[0-9A-Za-z.-]+\s*[:.-]*|Disposici[óo]n\s+(?:Final|Transitoria|General|Reformatoria|Derogatoria)\s+[a-zA-Z0-9áéíóúÁÉÍÓÚ]+\s*[:.-]*)\s*/i, '')
    .trim();

  let finalTitle = '';
  if (structType === 'transitory') finalTitle = `Disposición Transitoria ${rawNum}${cleanHeader ? ': ' + cleanHeader : ''}`;
  else if (structType === 'final') finalTitle = `Disposición Final ${rawNum}${cleanHeader ? ': ' + cleanHeader : ''}`;
  else if (structType === 'reform') finalTitle = `Disposición Reformatoria ${rawNum}${cleanHeader ? ': ' + cleanHeader : ''}`;
  else if (structType === 'other') finalTitle = `Disposición General ${rawNum}${cleanHeader ? ': ' + cleanHeader : ''}`;
  else finalTitle = cleanHeader ? `Art. ${rawNum}: ${cleanHeader}` : `Art. ${rawNum}`;

  const normTables = normalizeTablesList(art.tablas_normativas, rawNum, finalTitle);
  const targetNormCode = normalizeNormCode(art.reforma_norma_objetivo);
  const targetArtId = normalizeTargetArtId(art.reforma_articulo_objetivo);

  const extraReforms = Array.isArray(art.reformas_adicionales)
    ? art.reformas_adicionales.map((er) => {
        const erArtId = normalizeTargetArtId(er.reforma_articulo_objetivo || er.reforms_target_article_identifier);
        return {
          reforma_norma_objetivo: normalizeNormCode(er.reforma_norma_objetivo || er.reforms_target_norm_code || targetNormCode),
          reforma_articulo_objetivo: erArtId,
          reforma_tipo_cambio: er.reforma_tipo_cambio || er.reform_change_type || 'added',
          reforma_titulo_consolidado: er.reforma_titulo_consolidado || er.reformed_target_title || `Art. ${erArtId}`,
          texto_consolidado_post_reforma: er.texto_consolidado_post_reforma || er.reformed_target_content || '',
          resumen_reforma: er.resumen_reforma || er.summary_change || art.resumen_reforma || null,
          tablas_normativas: normalizeTablesList(er.tablas_normativas || er.normative_tables, erArtId || rawNum, er.reforma_titulo_consolidado || `Art. ${erArtId}`)
        };
      }).filter(er => er.reforma_norma_objetivo && er.reforma_articulo_objetivo && er.texto_consolidado_post_reforma)
    : [];

  // Auto-enriquecer conceptos verticales clave por contenido
  const conceptsSet = new Set(Array.isArray(art.conceptos_verticales) ? art.conceptos_verticales : []);
  const combinedText = `${finalTitle} ${art.titulo_padre || ''} ${art.capitulo_padre || ''} ${art.resumen_reforma || ''}`.toUpperCase();
  if (combinedText.includes('SIMPLIFICADO') || combinedText.includes('RISE') || (targetNormCode === 'LRTI' && String(targetArtId || '').startsWith('97.'))) {
    conceptsSet.add('RISE');
  }
  if (combinedText.includes('SALIDA DE DIVISAS') || combinedText.includes('ISD')) {
    conceptsSet.add('ISD');
  }
  if (combinedText.includes('CONSUMOS ESPECIALES') || combinedText.includes('ICE')) {
    conceptsSet.add('ICE');
  }

  consolidatedArticles.push({
    structure_type: structType,
    identifier: rawNum,
    title: finalTitle,
    parent_title: art.titulo_padre || tituloNorma || null,
    parent_chapter: art.capitulo_padre || null,
    content: art.texto_completo_markdown || art.contenido || '',
    vertical_concepts: Array.from(conceptsSet),
    has_normative_table: normTables.length > 0,
    normative_tables: normTables,
    detected_relations: Array.isArray(art.relaciones_detectadas) ? art.relaciones_detectadas : [],
    normative_type: normType,
    issuing_entity: actMeta.entidad_emisora || act.entidad_emisora || null,
    tax_periodicity: periodicity,
    is_fe_erratas: isFeErratas,
    valid_from: expressValidFrom,
    valid_until: null,
    official_registry: roCite,
    reform_source_cite: tituloNorma ? `${tituloNorma} (${roCite})` : `${normCode} (${roCite})`,
    summary_change: art.resumen_reforma || null,
    observations: `${roCite}`,
    reforms_target_norm_code: targetNormCode,
    reforms_target_norm_name: art.reforma_nombre_norma_objetivo || null,
    reforms_target_article_identifier: targetArtId,
    reform_change_type: art.reforma_tipo_cambio || null,
    reformed_target_title: art.reforma_titulo_consolidado || null,
    reformed_target_content: art.texto_consolidado_post_reforma || null,
    reformas_adicionales: extraReforms,
    review_status: 'approved'
  });
}

const versionTitle = tituloNorma.includes('Registro Oficial') ? tituloNorma : `${tituloNorma} (${roCite})`;

return [{
  json: {
    _has_articles: consolidatedArticles.length > 0,
    is_webhook: Boolean(meta.is_webhook),
    file_name: meta.file_name || null,
    google_drive_file_id: meta.google_drive_file_id || null,
