const unified = $('Unificar Meta Base64').first()?.json || {};
const meta = unified.meta || {};
const resp = $input.first()?.json || {};

if (resp.error) {
  throw new Error(`Error API Gemini (Planificador): ${JSON.stringify(resp.error)}`);
}

const candidate = resp.candidates?.[0];
const finishReason = candidate?.finishReason;
let rawText = candidate?.content?.parts?.[0]?.text || resp.text || '';
if (!rawText) {
  throw new Error(`Gemini Planificador no devolvió contenido (finishReason=${finishReason || 'unknown'})`);
}

const tryParseJsonWithRepair = (text) => {
  let clean = String(text || '').trim();
  if (clean.startsWith('```')) {
    clean = clean.replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/i, '').trim();
  }
  clean = clean
    .replace(/\\([“”«»])/g, '$1')
    .replace(/\\([^"\\/bfnrtu])/g, '$1');
  try { return JSON.parse(clean); } catch (_) {}
  if (clean.endsWith('\\')) clean = clean.slice(0, -1);
  let inString = false, escaped = false;
  const stack = [];
  for (let i = 0; i < clean.length; i++) {
    const ch = clean[i];
    if (escaped) { escaped = false; continue; }
    if (ch === '\\' && inString) { escaped = true; continue; }
    if (ch === '"') { inString = !inString; continue; }
    if (!inString) {
      if (ch === '{') stack.push('}');
      else if (ch === '[') stack.push(']');
      else if ((ch === '}' || ch === ']') && stack.length && stack[stack.length - 1] === ch) stack.pop();
    }
  }
  let repaired = clean;
  if (inString) repaired += '"';
  while (stack.length > 0) repaired += '\n' + stack.pop();
  return JSON.parse(repaired);
};

const parsed = tryParseJsonWithRepair(rawText);

const roCite = parsed.registro_oficial_cita || parsed.registro_oficial_detectado || meta.official_registry_cite || 'Registro Oficial';
const rawDate = parsed.registro_oficial_fecha || meta.published_on;
const roDate = /^\d{4}-\d{2}-\d{2}$/.test(String(rawDate || ''))
  ? String(rawDate)
  : (/^\d{4}-\d{2}-\d{2}$/.test(String(meta.published_on || '')) ? String(meta.published_on) : new Date().toISOString().split('T')[0]);

const normalizeNormCode = (code, title, roDateStr, fileName) => {
  let c = String(code || '').trim().toUpperCase();
  const t = String(title || '').toUpperCase();
  const fn = String(fileName || '').toUpperCase();

  if (fn.includes('20071229_242') || (t.includes('EQUIDAD TRIBUTARIA') && roDateStr.startsWith('2007'))) {
    if (!c.startsWith('NAC-') && !c.startsWith('DE-')) return 'LEY-2007-242';
  }
  if (!c) return null;
  const decMatch = c.match(/(?:DECRETO(?:\s+EJECUTIVO)?|DEC|NO\.?)\s*[-_N°#]?\s*(\d+)/i);
  if (decMatch && !c.includes('LEY') && !c.includes('RESOLUCI') && !c.includes('CIRCULAR')) {
    return 'DE-' + decMatch[1];
  }
  if (c.startsWith('NO.-') && /^NO\.-\d+$/.test(c)) {
    return 'DE-' + c.replace('NO.-', '');
  }
  if (c === 'RLRTI' || c === 'REGLAMENTO LRTI') return 'RALRTI';
  if (c === 'CODIGO TRIBUTARIO' || c === 'CÓDIGO TRIBUTARIO') return 'CT';
  if (c === 'LEY DE REGIMEN TRIBUTARIO INTERNO' || c === 'LEY DE RÉGIMEN TRIBUTARIO INTERNO') return 'LRTI';
  return c.replace(/\s+/g, '-');
};

const acts = Array.isArray(parsed.actos_detectados) ? parsed.actos_detectados : [];

if (!acts.length) {
  return [{
    json: {
      _has_articles: false,
      is_webhook: Boolean(meta.is_webhook),
      status: 'no_tax_content',
      file_name: meta.file_name || null,
      google_drive_file_id: meta.google_drive_file_id || null,
      ro_cite: roCite,
      ro_date: roDate
    }
  }];
}

const blockQueue = [];

for (let actIdx = 0; actIdx < acts.length; actIdx++) {
  const act = acts[actIdx] || {};
  let normCode = normalizeNormCode(act.codigo_norma, act.titulo_norma, roDate, meta.file_name);
  if (meta.norm_code && meta.folder_category !== '00_registros_oficiales' && acts.length === 1) {
    normCode = normalizeNormCode(meta.norm_code, act.titulo_norma, roDate, meta.file_name);
  }
  if (!normCode) normCode = `NORMA-${roDate.replace(/-/g, '')}-${actIdx + 1}`;

  const rawBlocks = Array.isArray(act.bloques) && act.bloques.length > 0
    ? act.bloques
    : [{
        bloque_num: 1,
        descripcion_bloque: 'Extracción completa del acto normativo',
        rango_inicio: 'Inicio',
        rango_fin: 'Fin',
        instruccion_foco: 'Extraer todos los artículos, disposiciones y tablas del acto normativo.'
      }];

  for (let bIdx = 0; bIdx < rawBlocks.length; bIdx++) {
    const blk = rawBlocks[bIdx] || {};
    const actMetaObj = {
      codigo_norma: normCode,
      titulo_norma: act.titulo_norma || normCode,
      tipo_norma: act.tipo_norma || 'law',
      entidad_emisora: act.entidad_emisora || null,
      es_fe_erratas: Boolean(act.es_fe_erratas),
      periodicidad_tributaria: act.periodicidad_tributaria || 'monthly',
      vigencia_expresa_fecha: act.vigencia_expresa_fecha || roDate
    };
    const blockSpecObj = {
      bloque_num: blk.bloque_num || (bIdx + 1),
      total_bloques_acto: rawBlocks.length,
      descripcion_bloque: blk.descripcion_bloque || `Bloque ${bIdx + 1} de ${rawBlocks.length}`,
      rango_inicio: blk.rango_inicio || 'Inicio',
      rango_fin: blk.rango_fin || 'Fin',
      instruccion_foco: blk.instruccion_foco || 'Extraer todos los artículos y disposiciones de este bloque.'
    };

    const promptText = `Eres un jurista tributario ecuatoriano de élite y arquitecto de datos normativos de SmartLex Ecuador.

CONTEXTO DEL DOCUMENTO Y BLOQUE ACTUAL (PASADA 2 — EXTRACCIÓN PROFUNDA POR BLOQUE):
- Registro Oficial: ${roCite} (Fecha: ${roDate})
- Acto Normativo Objetivo: ${actMetaObj.titulo_norma} (Código: ${actMetaObj.codigo_norma}, Tipo: ${actMetaObj.tipo_norma})
- Entidad Emisora: ${actMetaObj.entidad_emisora || 'Detectar en PDF'}
- BLOQUE ASIGNADO: Bloque ${blockSpecObj.bloque_num} de ${blockSpecObj.total_bloques_acto}
- Descripción del Bloque: ${blockSpecObj.descripcion_bloque}
- Rango estricto a extraer en esta llamada: Desde [${blockSpecObj.rango_inicio}] hasta [${blockSpecObj.rango_fin}]
- Instrucción de foco: ${blockSpecObj.instruccion_foco}

TAREA:
Extrae ÚNICAMENTE y de forma 100 % ÍNTEGRA todos los artículos, disposiciones y tablas que pertenecen al BLOQUE ASIGNADO (${blockSpecObj.rango_inicio} a ${blockSpecObj.rango_fin}) del acto normativo ${actMetaObj.titulo_norma}.
No resumas ni omitas ningún artículo dentro de este rango. No extraigas artículos de otros bloques fuera de este rango.

Devuelve ÚNICAMENTE un objeto JSON válido con este esquema exacto:
